5	namespace AtrioTeam\DigitalHub\Tags\Filament;
6	
7	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
8	use AtrioTeam\DigitalHub\Tags\Models\Tag;
9	use AtrioTeam\DigitalHub\Tags\Models\TagCategory;
10	use Closure;
11	use Filament\Forms\Components\Select;
12	use Filament\Schemas\Components\Section;
13	use Illuminate\Database\Eloquent\Builder;
14	use Illuminate\Database\Eloquent\Model;
15	use Illuminate\Database\Eloquent\Relations\MorphToMany;
16	
17	/**
18	 * Sezione dei tag associabili, con vincolo rigido: considera solo i gruppi
19	 * filtrati per l'entità data e per il target dato (entity|asset) e produce un
20	 * Select a scelta multipla per ogni categoria di quei gruppi, con i soli tag
21	 * della categoria come opzioni. Condiviso fra i form delle entità e il picker
22	 * degli asset nell'AssetManager.
23	 */
24	class TagPicker
25	{
26	    /**
27	     * Picker legato alla relazione `tags` del record del form (entità che usa
28	     * HasTags): ogni select carica/sincronizza sul pivot `taggables` i soli tag
29	     * della propria categoria, senza toccare quelli delle altre.
30	     *
31	     * `$scopeGroupsUsing` (opzionale) restringe ulteriormente i gruppi: riceve
32	     * la query dei TagGroup come parametro nominato `query` e viene valutata da
33	     * Filament, quindi supporta l'injection dei parametri di contesto (es.
34	     * `$livewire`). Permette all'app vincoli propri (es. la Destinazione
35	     * Category1) senza che il package li conosca.
36	     */
37	    public static function make(string $entityAlias, TagTarget $target, ?Closure $scopeGroupsUsing = null): Section
38	    {
39	        // schema lazy: i gruppi possono dipendere dal contesto ($livewire) via
40	        // $scopeGroupsUsing, valutato da Filament sul componente
41	        return self::section()->schema(function (Section $component) use ($entityAlias, $target, $scopeGroupsUsing): array {
42	            $scopeGroups = $scopeGroupsUsing === null ? null : function (Builder $groupQuery) use ($component, $scopeGroupsUsing): void {
43	                $component->evaluate($scopeGroupsUsing, ['query' => $groupQuery]);
44	            };
45	
46	            return array_map(
47	                fn (TagCategory $category): Select => self::relationshipSelect($category),
48	                self::categories($entityAlias, $target, $scopeGroups),
49	            );
50	        });
51	    }
52	
53	    /**
54	     * Picker "standalone" (senza relationship): lo stato è un array di id tag
55	     * per categoria, sotto la chiave `tags` (`tags.{categoryId}` => int[]).
56	     * Per contesti senza record bindato al form (es. azione nell'AssetManager),
57	     * dove fill/sync sono gestiti a mano dal chiamante.
58	     */
59	    public static function makeStandalone(string $entityAlias, TagTarget $target): Section
60	    {
61	        return self::section()->schema(fn (): array => array_map(
62	            fn (TagCategory $category): Select => self::categorySelect($category),
63	            self::categories($entityAlias, $target, null),
64	        ));
65	    }
66	
67	    private static function section(): Section
68	    {
69	        return Section::make(__('digital-hub::tag.model_plural'))->columns(2);
70	    }
71	
72	    /**
73	     * Select della categoria per la variante con relationship: stato caricato e
74	     * salvato a mano sul pivot (via gli stessi hook usati da
75	     * Select::relationship()), limitato ai tag della categoria perché più
76	     * select condividono la stessa relazione `tags`.
77	     */
78	    private static function relationshipSelect(TagCategory $category): Select
79	    {
80	        $categoryId = (int) $category->id;
81	        $categoryTagIds = array_map(fn ($id): int => (int) $id, $category->tags->modelKeys());
82	
83	        return self::categorySelect($category)
84	            ->dehydrated(false)
85	            ->loadStateFromRelationshipsUsing(function (Select $component, ?Model $record) use ($categoryId): void {
86	                if ($record === null) {
87	                    return;
88	                }
89	
90	                $component->state(
91	                    self::tagsRelation($record)
92	                        ->where('tag_category_id', $categoryId)
93	                        ->pluck('tags.id')
94	                        ->all(),
95	                );
96	            })
97	            ->saveRelationshipsUsing(function (Select $component, ?Model $record) use ($categoryTagIds): void {
98	                if ($record === null) {
99	                    return;
100	                }
101	
102	                $selected = array_values(array_intersect(
103	                    array_map(fn (mixed $id): int => is_scalar($id) ? (int) $id : 0, (array) $component->getState()),
104	                    $categoryTagIds,
105	                ));
106	
107	                $relation = self::tagsRelation($record);
108	                $relation->detach(array_values(array_diff($categoryTagIds, $selected)));
109	                $relation->syncWithoutDetaching($selected);
110	            });
111	    }
112	
113	    /**
114	     * Select multiplo con i tag della categoria come opzioni. Lo statePath
115	     * annidato `tags.{categoryId}` tiene tutte le selezioni sotto `tags`.
116	     */
117	    private static function categorySelect(TagCategory $category): Select
118	    {
119	        $options = [];
120	        foreach ($category->tags as $tag) {
121	            $options[(int) $tag->id] = (string) $tag->name;
122	        }
123	
124	        return Select::make('tags.' . (int) $category->id)
125	            ->label((string) $category->name)
126	            ->multiple()
127	            ->searchable()
128	            ->options($options)
129	            ->default([]);
130	    }
131	
132	    /**
133	     * Categorie (con i loro tag) dei gruppi filtrati per entità e target, più
134	     * l'eventuale vincolo aggiuntivo sui gruppi passato dal chiamante. Le
135	     * categorie senza tag sono escluse.
136	     *
137	     * @param (Closure(Builder<\Illuminate\Database\Eloquent\Model>): void)|null $scopeGroups query dei TagGroup
138	     * @return array<int, TagCategory>
139	     */
140	    private static function categories(string $entityAlias, TagTarget $target, ?Closure $scopeGroups): array
141	    {
142	        return TagCategory::query()
143	            ->whereHas('group', function (Builder $groupQuery) use ($entityAlias, $target, $scopeGroups): void {
144	                $groupQuery
145	                    ->where('entity_type', $entityAlias)
146	                    ->where('target', $target->value);
147	
148	                if ($scopeGroups !== null) {
149	                    $scopeGroups($groupQuery);
150	                }
151	            })
152	            ->whereHas('tags')
153	            ->with('tags')
154	            ->orderBy('id')
155	            ->get()
156	            ->all();
157	    }
158	
159	    /**
160	     * Relazione tags() del record (HasTags di spatie), tipizzata qui perché dal
161	     * form il record arriva come Model generico.
162	     *
163	     * @return MorphToMany<Tag, Model>
164	     */
165	    private static function tagsRelation(Model $record): MorphToMany
166	    {
167	        assert(method_exists($record, 'tags'));
168	
169	        /** @var MorphToMany<Tag, Model> $relation */
170	        $relation = $record->tags();
171	
172	        return $relation;
173	    }
174	}
